### cot
1. Check if the specified JSON file exists at the given path; if not, raise a ValueError.
2. Load the JSON data from the file.
3. Validate that all required fields defined in the schema are present in the JSON object.
4. Verify that the data types of the properties in the JSON object match the types specified in the schema.
5. Validate the email format using the provided regular expression if the email field is present.
6. Return the value of the requested attribute from the JSON data, or raise a ValueError if the attribute is missing or validation fails.

### code
```python
import json
import os
import re

def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError:
            raise ValueError("Invalid JSON format")

    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Required attribute '{field}' is missing")

    properties = INPUT_JSON.get("properties", {})
    for key, value in data.items():
        if key in properties:
            expected_type = properties[key].get("type")
            if not isinstance(value, expected_type):
                raise ValueError(f"Type mismatch for attribute '{key}'")

            if key == "email":
                if not re.match(EMAIL_REGEX, value):
                    raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON")

    return data[attribute]
